echo "=== 进程详情 ==="
ps -p $(cat /data/training_tumvie.pid 2>/dev/null) -o pid,lstart,etime,stat --no-headers 2>/dev/null || echo "已结束"
echo ""
echo "=== 训练阶段总结 ==="
python3 << 'PYEOF'
with open('/data/training_tumvie_mocap-desk.log') as f:
    text = f.read()

import re

# Phase markers
phases = []
if 'random initialization' in text:
    phases.append('✅ 随机初始化 (4500 iter)')
if 'finished initialization' in text:
    phases.append('  → Marigold 深度估计')
if 'sfm' in text.lower():
    phases.append('🔄 SfM 精化 (深度图引导, 4501 iter) - 进行中')
if 'finished BA' in text:
    phases.append('  → 增量 Tracking + BA')
if 'global BA' in text:
    phases.append('  → 全局 BA')
if 'finished =' in text:
    phases.append('✅ 完成')

for p in phases:
    print(p)

# Latest iteration
iters = re.findall(r'iter (\d+),', text)
if iters:
    # Find the last batch of iterations
    # They come in groups per phase
    all_iters = [int(x) for x in iters]
    print(f'\n最新: iter {all_iters[-1]} (SfM 阶段)')

    # Per-phase iteration ranges
    phase1_iters = [int(x) for x in re.findall(r'iter (\d+),', text[:text.index('finished initialization')])] if 'finished initialization' in text else []
    if phase1_iters:
        print(f'阶段1 随机初始化: iter {max(phase1_iters)}/4501')

    sfm_start = text.index('sfm') if 'sfm' in text.lower() else len(text)
    if sfm_start < len(text):
        sfm_iters = [int(x) for x in re.findall(r'iter (\d+),', text[sfm_start:])]
        if sfm_iters:
            print(f'阶段2 SfM: iter {max(sfm_iters)}/4501')

# Loss trend
losses = [(int(m[0]), float(m[1])) for m in re.findall(r'iter (\d+), loss=([\d.]+)', text)]
if losses:
    latest = losses[-1]
    try:
        # Find iter 0 of current phase
        last_phase_start = None
        for i, (it, l) in enumerate(losses):
            if it == 0 and i > len(losses)//2:
                last_phase_start = i
                break
        if last_phase_start:
            first_loss = losses[last_phase_start][1]
            print(f'\nSfM Loss: {first_loss:.4f} → {latest[1]:.4f} (↓{(1-latest[1]/first_loss)*100:.0f}%)')
        else:
            print(f'\nLoss: {latest[1]:.4f}')
    except:
        print(f'\nLatest loss: {latest[1]:.4f}')
PYEOF
